\title{A One-Parameter Deformation of the Eulerian Numbers and Its Recurrence}
\author{Aristotle}
\date{June 28, 2026}

\begin{document}

\begin{abstract}
We introduce a one-parameter family of real numbers $A(n,k,s)$, the \emph{extended
Eulerian numbers}, defined for $n,k \in \N$ and a real shift $s$ by the alternating
binomial closed form
\[
A(n,k,s) = \sum_{i=0}^{k} (-1)^i \binom{n+1}{i}\,(k+1-i-s)^n .
\]
At $s=0$ this is Worpitzky's closed form for the Eulerian numbers $\eul{n}{k}$,
which count permutations of $\{1,\dots,n\}$ with exactly $k$ descents. Our main
theorem is that, although $A$ is \emph{defined} by the closed form rather than by a
recurrence, it satisfies the deformed Eulerian recurrence
\[
A(n+1,k+1,s) = (k+2-s)\,A(n,k+1,s) + (n-k+s)\,A(n,k,s),
\]
with boundary values $A(0,0,s)=1$, $A(0,k+1,s)=0$, and the left-edge identity
$A(n,0,s)=(1-s)^n$. The proof is elementary and non-circular: it reduces, through
three lemmas on alternating binomial sums, to Pascal's rule and the absorption
identity for binomial coefficients. All statements have been formalized and
machine-checked. We provide proof sketches, an exact rational tabulation algorithm,
numerical corroboration of the $s$-independent row-sum identity
$\sum_k A(n,k,s)=n!$, and a program of conjectural extensions.
\end{abstract}

\maketitle

\section{Introduction}

The Eulerian numbers $\eul{n}{k}$ count permutations of $\{1,\dots,n\}$ by descents.
They appear in Worpitzky's identity expressing monomials in the basis of binomial
polynomials, in the volumes of hypersimplices, and as coefficients of the Eulerian
polynomials in $\sum_{m\ge 0} m^n t^m = A_n(t)/(1-t)^{n+1}$. They are usually
\emph{defined} by the triangular recurrence
\[
\eul{n+1}{k+1} = (k+2)\eul{n}{k+1} + (n-k)\eul{n}{k}.
\]

A recurring theme in combinatorics is the deformation of such discrete families by a
continuous parameter, exposing which identities are rigid and which are flexible. We
carry out such a deformation by inserting a single real shift $s$ into Worpitzky's
closed form, and we ask which classical identities survive.

The principal subtlety is logical hygiene. Defining a deformed family by a deformed
recurrence would make any statement that it satisfies the recurrence tautological.
We instead take the closed form as the \emph{sole} definition and \emph{prove} the
recurrence as a genuine consequence.

\paragraph{Contributions.}
(1)~Definition~\ref{def:A} of $A(n,k,s)$ via the closed form;
(2)~Theorem~\ref{thm:rec} (the deformed recurrence), proved from the closed form;
(3)~Propositions~\ref{prop:apex}--\ref{prop:edge} (boundary identities, including
$A(n,0,s)=(1-s)^n$);
(4)~Lemmas~\ref{lem:pascal}--\ref{lem:recombine}, an elementary toolkit reducing
everything to Pascal's rule and the absorption identity;
(5)~an exact tabulation algorithm and numerical evidence for $\sum_k A(n,k,s)=n!$.

\section{Definitions}

Throughout, $n,k$ range over $\N=\{0,1,2,\dots\}$, $s\in\R$, and $\binom{a}{b}$ is
the natural-number binomial coefficient (zero for $b>a$), cast into $\R$. Empty sums
are zero.

\begin{definition}[Extended Eulerian numbers; Lean: \texttt{A}]\label{def:A}
For $n,k\in\N$ and $s\in\R$,
\[
A(n,k,s) = \sum_{i=0}^{k} (-1)^i \binom{n+1}{i}\,(k+1-i-s)^n .
\]
We use the out-of-range convention $A(n,k,s)=0$ for $k<0$ or $k>n$. At $s=0$ this is
the Worpitzky closed form, so $A(n,k,0)=\eul{n}{k}$.
\end{definition}

\begin{proposition}[Rebased form; Lean: \texttt{A\_eq}]\label{prop:rebase}
\[
A(n,k,s) = \sum_{i=0}^{k} (-1)^i \binom{n+1}{i}\,\bigl((k+1-s)-i\bigr)^n .
\]
\end{proposition}

\begin{proof}[Proof sketch]
Termwise, $k+1-i-s=(k+1-s)-i$; the summands are identical.
\end{proof}

The rebased form isolates the base point $c:=k+1-s$ and exhibits each row as an
alternating binomial sum $\sum_i (-1)^i \binom{n+1}{i}(c-i)^n$, the shape handled in
Section~\ref{sec:toolkit}.

\section{Boundary values}

\begin{proposition}[Apex; Lean: \texttt{A\_zero\_zero}]\label{prop:apex}
$A(0,0,s)=1$ for all $s\in\R$.
\end{proposition}
\begin{proof}[Proof sketch]
The sum has the single term $i=0$, equal to $\binom{1}{0}(1-s)^0=1$.
\end{proof}

\begin{proposition}[Top row; Lean: \texttt{A\_zero\_succ}]\label{prop:toprow}
$A(0,k+1,s)=0$ for all $k\in\N$, $s\in\R$.
\end{proposition}
\begin{proof}[Proof sketch]
At $n=0$ every power is $1$, so $A(0,m,s)=\sum_{i=0}^m (-1)^i\binom{1}{i}$. Since
$\binom{1}{i}=0$ for $i\ge2$, this equals $\binom{1}{0}-\binom{1}{1}=0$ for $m\ge1$.
\end{proof}

\begin{proposition}[Left edge; Lean: \texttt{A\_at\_zero}]\label{prop:edge}
$A(n,0,s)=(1-s)^n$ for all $n\in\N$, $s\in\R$.
\end{proposition}
\begin{proof}[Proof sketch]
At $k=0$ the single term $i=0$ is $\binom{n+1}{0}(1-s)^n=(1-s)^n$.
\end{proof}

Proposition~\ref{prop:edge} is the deformation's signature: the classical left edge
$\eul{n}{0}=1$ bends into the geometric sequence $(1-s)^n$, and acts as the initial
datum selecting the parameter $s$.

\section{The combinatorial toolkit}\label{sec:toolkit}

\begin{lemma}[Pascal's rule; Lean: \texttt{choose\_succ\_succ\_cast}]\label{lem:pascal}
$\displaystyle \binom{n+2}{j+1} = \binom{n+1}{j} + \binom{n+1}{j+1}.$
\end{lemma}

\begin{lemma}[Absorption; Lean: \texttt{choose\_absorb\_cast}]\label{lem:absorb}
$\displaystyle (j+1)\binom{n+1}{j+1} = (n+1)\binom{n}{j}.$
\end{lemma}

These are the only external inputs.

\begin{lemma}[Pascal split; Lean: \texttt{alt\_binom\_pascal\_split}]\label{lem:split}
For all $n,m,q\in\N$ and $c\in\R$,
\[
\sum_{i=0}^{m+1} (-1)^i \binom{n+2}{i}(c-i)^q
= \sum_{i=0}^{m+1} (-1)^i \binom{n+1}{i}(c-i)^q
- \sum_{j=0}^{m} (-1)^j \binom{n+1}{j}(c-1-j)^q .
\]
\end{lemma}
\begin{proof}[Proof sketch]
Apply Lemma~\ref{lem:pascal} to each $\binom{n+2}{i}$, splitting the left sum; reindex
the $\binom{n+1}{i-1}$ part by $j=i-1$, which shifts the base to $c-1-j$ and
introduces $(-1)^{j+1}$, giving the stated difference.
\end{proof}

\begin{lemma}[Linear-factor absorption; Lean: \texttt{alt\_binom\_absorb\_sum}]\label{lem:absorbsum}
For all $n,m,q\in\N$ and $c\in\R$,
\[
\sum_{i=0}^{m} (-1)^i \binom{n+1}{i}\, i\,(c-i)^q
= -(n+1)\sum_{j=0}^{m-1} (-1)^j \binom{n}{j}(c-1-j)^q .
\]
\end{lemma}
\begin{proof}[Proof sketch]
The $i=0$ term vanishes; for $i\ge1$ use $i\binom{n+1}{i}=(n+1)\binom{n}{i-1}$
(Lemma~\ref{lem:absorb}), reindex $j=i-1$, and collect $(-1)^i=-(-1)^j$.
\end{proof}

\begin{lemma}[Pascal recombine; Lean: \texttt{alt\_binom\_pascal\_recombine}]\label{lem:recombine}
For all $n,m,q\in\N$ and $d\in\R$,
\[
\sum_{j=0}^{m} (-1)^j \binom{n}{j}(d-j)^q
- \sum_{j=0}^{m-1} (-1)^j \binom{n}{j}(d-1-j)^q
= \sum_{j=0}^{m} (-1)^j \binom{n+1}{j}(d-j)^q .
\]
\end{lemma}
\begin{proof}[Proof sketch]
The reverse of Lemma~\ref{lem:split}: reindex the second sum by $j\mapsto j+1$ so both
share base $d-j$, then combine $\binom{n}{j}+\binom{n}{j-1}=\binom{n+1}{j}$.
\end{proof}

None of these lemmas mentions Eulerian numbers, so using them introduces no
circularity.

\section{The main recurrence}

\begin{theorem}[Extended Eulerian recurrence; Lean: \texttt{A\_recurrence}]\label{thm:rec}
For all $n,k\in\N$ and $s\in\R$,
\[
A(n+1,k+1,s) = (k+2-s)\,A(n,k+1,s) + (n-k+s)\,A(n,k,s).
\]
\end{theorem}

\begin{proof}[Proof sketch]
Write $c:=(k+2)-s$, so by Proposition~\ref{prop:rebase},
$A(n+1,k+1,s)=\sum_{i=0}^{k+1}(-1)^i\binom{n+2}{i}(c-i)^{n+1}$.

\emph{(i) Split.} By Lemma~\ref{lem:split} (with $m=k$, $q=n+1$),
$A(n+1,k+1,s)=S_1-S_2$, where
\[
S_1=\sum_{i=0}^{k+1}(-1)^i\binom{n+1}{i}(c-i)^{n+1},\quad
S_2=\sum_{j=0}^{k}(-1)^j\binom{n+1}{j}(c-1-j)^{n+1},
\]
and $c-1=(k+1)-s$ is the base point of row $k$.

\emph{(ii) Lower the exponent.} Write $(c-i)^{n+1}=c\,(c-i)^n-i\,(c-i)^n$ in each
$S_\bullet$. The linear part is exactly the sum to which Lemma~\ref{lem:absorbsum}
applies, converting a $\binom{n+1}{i}\,i$ weight into $(n+1)\binom{n}{j}$ with the
base shifted by one. Thus $S_1=c\,A(n,k+1,s)+(n+1)R_1$ and
$S_2=(c-1)\,A(n,k,s)+(n+1)R_2$, where $R_1,R_2$ are alternating
$\binom{n}{\cdot}$ sums differing by exactly one base shift.

\emph{(iii) Recombine.} By Lemma~\ref{lem:recombine}, $R_1-R_2$ collapses into a
single $\binom{n+1}{\cdot}$ sum, i.e.\ a copy of $A(n,\cdot,s)$. Collecting the
constant coefficients from the $c\,(c-i)^n$ parts and the $\pm(n+1)$ factors from
the absorption steps, with $c=(k+2)-s$ and $c-1=(k+1)-s$, the total coefficient of
$A(n,k+1,s)$ is $(k+2-s)$ and that of $A(n,k,s)$ is $(n-k+s)$.
\end{proof}

The shift $s$ is inert throughout, entering only via the base points $c,c-1$ and
carried verbatim into the final coefficients.

\begin{corollary}[Balanced weights]\label{cor:balanced}
$(k+2-s)+(n-k+s)=n+2$, independent of $k$ and $s$.
\end{corollary}

\begin{corollary}[Classical specialization]\label{cor:classical}
At $s=0$, Theorem~\ref{thm:rec} is $\eul{n+1}{k+1}=(k+2)\eul{n}{k+1}+(n-k)\eul{n}{k}$,
with $A(n,k,0)=\eul{n}{k}$.
\end{corollary}

\section{Algorithms and numerical results}

\subsection{Exact tabulation}
Theorem~\ref{thm:rec} with the boundary values yields an $O(n^2)$ dynamic program
in exact rational arithmetic. Maintaining row $(A(m,j,s))_{j=0}^m$, the next row is
\[
A(m+1,j,s)=(j+1-s)\,A(m,j,s)+(m-j+s)\,A(m,j-1,s),
\]
with out-of-range entries $0$ and $A(0,0,s)=1$.

\subsection{Cross-check}
Computing $A(n,k,s)$ from Definition~\ref{def:A} and from the recurrence agrees for
all $0\le k\le n\le 7$ and all tested $s\in\{0,\tfrac13,\tfrac12,\tfrac{7}{10},1\}$.

\subsection{Factorial row-sum}
\begin{observation}\label{obs:rowsum}
Numerically, $\sum_{k=0}^n A(n,k,s)=n!$ for all tested $n$ and $s$.
\end{observation}
The mechanism is Corollary~\ref{cor:balanced}: summing the recurrence over a row
multiplies the row sum by the constant total weight $n+2$ while the $\pm s$ terms
cancel, so the totals follow the factorials from $A(0,0,s)=1$.

\subsection{Worked instance}
At $s=\tfrac12$, row $n=2$ is $(\tfrac14,\tfrac32,\tfrac14)$ (sum $2=2!$). By
Theorem~\ref{thm:rec} with $n=2$, $k=0$,
\[
A(3,1,\tfrac12)=(0+2-\tfrac12)\tfrac32+(2-0+\tfrac12)\tfrac14
=\tfrac94+\tfrac58=\tfrac{23}{8},
\]
matching the closed form.

\section{Discussion and future directions}

The construction isolates a dichotomy: the left edge is flexible
($A(n,0,s)=(1-s)^n$), while the row sum is rigid ($\sum_k A(n,k,s)=n!$), because $s$
enters the recurrence antisymmetrically (Corollary~\ref{cor:balanced}).

\begin{enumerate}
\item \textbf{Row-sum / normalization.} $\sum_{k=0}^n A(n,k,s)=n!$ for every $s$,
provable by telescoping induction on $n$ using Theorem~\ref{thm:rec} and
Corollary~\ref{cor:balanced}.
\item \textbf{Symmetry.} Whether a shifted reflection $A(n,k,s)=A(n,n-1-k,1-s)$ holds
(recovering $\eul{n}{k}=\eul{n}{n-1-k}$ at $s=0$) is open; numerics suggest the
precise statement needs adjustment.
\item \textbf{Worpitzky-type expansion.} Conjecturally
$(x-s)^n=\sum_{k=0}^{n-1}A(n,k,s)\binom{x-k}{n}$, equivalent to
Theorem~\ref{thm:rec} via the Pascal recurrence for $\binom{x-k}{n}$.
\item \textbf{Exponential generating function.} A one-parameter deformation of
$(t-1)/(t-e^{(t-1)x})$, with $s$ entering only through the initial condition
$A(n,0,s)=(1-s)^n$ (Proposition~\ref{prop:edge}).
\item \textbf{Log-concavity / real-rootedness.} For fixed $n$ and $s\in[0,1]$, is
$k\mapsto A(n,k,s)$ log-concave and the row polynomial real-rooted?
\end{enumerate}

\section{Conclusion}

We defined the extended Eulerian numbers by an explicit alternating binomial closed
form and proved, with full formal rigor and no circularity, that they obey the
deformed recurrence with boundary values $A(0,0,s)=1$, $A(0,k+1,s)=0$,
$A(n,0,s)=(1-s)^n$. The proof reduces to Pascal's rule and the absorption identity
through three lemmas on alternating binomial sums. The shift $s$ is structurally
inert in the recurrence, which explains the parameter-independent factorial row sum
and identifies $(1-s)^n$ as the datum selecting the deformation.

